export const tieredSavingsDefinitions={
  tieredSavings:{title:'Calculate interest by balance slice before comparing the average rate',fields:[
    ['balance','Constant deposit balance for the hypothetical full year (CAD)',15000,1000,100000,1000],
    ['topRate','Annual rate on only the balance above CAD 10,000 (%)',5,3,8,.25],
    ['flatRate','Comparison annual rate applied to the entire balance (%)',3.5,0,8,.25]
  ]}
};
export function tieredSavingsPlan(input){
  const slices=[{label:'First 5k at 1%',principal:Math.min(input.balance,5000),rate:.01},{label:'Next 5k at 3%',principal:Math.min(Math.max(0,input.balance-5000),5000),rate:.03},{label:'Above 10k at '+input.topRate+'%',principal:Math.max(0,input.balance-10000),rate:input.topRate/100}].map(s=>({...s,interest:s.principal*s.rate}));
  const interest=slices.reduce((sum,s)=>sum+s.interest,0),flatInterest=input.balance*input.flatRate/100;
  return {slices,interest,blended:interest/input.balance,flatInterest,difference:interest-flatInterest,allAtTop:input.balance*input.topRate/100};
}
export function tieredSavingsResult(kind,input){
  if(kind!=='tieredSavings')throw Error('Unknown tiered-savings topic.');
  const p=tieredSavingsPlan(input);
  return {metrics:[['Annual interest from the three balance slices',p.interest,'money'],['Blended annual interest divided by the whole deposit',p.blended,'percent'],['Annual interest: tiered schedule less the entered flat-rate comparison',p.difference,'money']],note:'Original hypothetical one-year deposit illustration, not a bank quote. A constant balance is held for a full year. Simple annual interest is paid once at the end, with no intra-year compounding, deposits, withdrawals, fees, tax, promotional window or balance qualification test. The first CAD 5,000 earns 1%; the next CAD 5,000 earns 3%; only the amount above CAD 10,000 earns the entered top rate. Crossing a threshold never reprices earlier slices. The comparison applies its entered flat rate to the same entire balance for the same full year. The blended rate is total annual interest divided by that balance. Actual accounts may use different tiers, all-balance rules, daily calculations, monthly credits or eligibility conditions. All rates and thresholds here are constructed assumptions, and no actual deposit-insurance eligibility, access terms or product recommendation is provided.',charts:[
    {id:'tiered-savings-interest-slices',type:'bar',title:'Each balance slice contributes its own amount of interest',unit:'money',unitLabel:'Interest in CAD for one full year; different principal in each slice',rows:p.slices.map(s=>({label:s.label,value:s.interest})),note:'Each bar is that slice’s principal multiplied by its own annual rate. The first two slices contain no more than CAD 5,000 each; the third contains only the balance above CAD 10,000. A zero bar means no principal is assigned to that slice, not that the listed rate has changed. Add the bars to obtain total annual interest.'},
    {id:'tiered-savings-headline-bridge',type:'waterfall',title:'Reconcile an all-at-top-rate estimate with the actual slice calculation',unit:'money',rows:[{label:'Entire balance multiplied by the top rate',value:p.allAtTop},{label:'Adjust the first slice to its 1% rate',value:-p.slices[0].principal*(input.topRate/100-.01)},{label:'Adjust the second slice to its 3% rate',value:-p.slices[1].principal*(input.topRate/100-.03)}],totalLabel:'Annual interest under the tiered rule',note:'The first bar is a deliberately simplified estimate, not another bank offer or a promised payment. The adjustments correct the rate on the occupied lower slices. The endpoint equals the sum of the interest bars above, including when the balance never reaches the highest slice.'},
    {id:'tiered-savings-blended-curve',type:'line',title:'The blended rate changes with the balance even when the rate table stays fixed',unit:'percent',unitLabel:'Annual interest divided by the entire constant balance (%)',xLabel:'Deposit balance (CAD thousands)',series:[{name:'Blended rate under the tiered schedule',rows:Array.from({length:50},(_,i)=>{const balance=(i+1)*1000;return {x:balance/1000,value:tieredSavingsPlan({...input,balance}).blended};})},{name:'Entered flat rate on the entire balance',rows:[{x:1,value:input.flatRate/100},{x:50,value:input.flatRate/100}],dash:true}],note:'The curve uses balances from CAD 1,000 to CAD 50,000 and keeps all tier rates fixed. The balance field does not move this fixed-range comparison; it selects the other figures and metrics. Each additional dollar above CAD 10,000 earns the top rate, but earlier dollars continue earning lower rates. The whole-balance average therefore remains below the top rate at every finite balance in this schedule.'},
    {id:'tiered-savings-flat-grid',type:'heatmap',title:'Compare interest dollars at the same balance and holding period',unit:'money',signed:true,columns:['2%','3%','4%','5%'],rows:[5000,10000,15000,25000].map(balance=>({label:'CAD '+balance/1000+'k',values:[2,3,4,5].map(flatRate=>tieredSavingsPlan({...input,balance,flatRate}).difference)})),unitLabel:'Annual tiered interest less flat-rate interest on the same full balance (CAD)',note:'Rows replace the balance; columns replace the annual flat comparison rate. The entered top-tier rate remains selected, while the lower slices stay at 1% and 3%. Each cell uses the same balance and year on both sides. Positive values favour the tiered rule before the excluded taxes, fees and account conditions. No cell represents an actual account quote or probability.'}
  ]};
}
